import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";
// Shared browser and standalone dimension rules. No I/O.
export const ruleset = "dimension-comparison/1.0.0";
const axes = ["length", "width", "height"];
const factors = { mm: 10n, cm: 100n, m: 10000n, in: 254n };
const isRecord = (value) => value !== null && typeof value === "object" && !Array.isArray(value);
// Six decimal places in the input; seven in millimetres after inch conversion.
function decimal(value, allowZero = false) {
  if (typeof value !== "string" || !/^(0|[1-9]\d{0,6})(\.\d{1,6})?$/.test(value)) return null;
  const [whole, fraction = ""] = value.split(".");
  const scaled = BigInt(whole) * 1000000n + BigInt(fraction.padEnd(6, "0"));
  if (scaled > 1000000000000n || (!allowZero && scaled === 0n)) return null;
  return scaled;
}
function millimetres(value) {
  const whole = value / 10000000n;
  const fraction = String(value % 10000000n).padStart(7, "0").replace(/0+$/, "");
  return String(whole) + (fraction ? "." + fraction : "");
}

export function compareDimensions(input) {
  const findings = [];
  const hold = (path, message) => findings.push({ code: "input-or-scope", path, message });
  const only = (record, keys, path) => {
    for (const key of Object.keys(record)) if (!keys.includes(key)) hold(`${path}.${key}`, "Unrecognized field; review the input contract.");
  };
  const result = (status, normalized = null) => ({
    schemaVersion: "1.0", ruleset, status, normalized, findings,
    scope: "Compares supplied dimensions and scope only. Evidence references are not opened or authenticated. A match does not establish physical fit, installation suitability, source accuracy, or provider acceptance.",
  });
  if (!isRecord(input)) {
    hold("$", "Expected a JSON object.");
    return result("hold");
  }
  only(input, ["schemaVersion", "source", "candidate", "toleranceMm"], "$");
  if (input.schemaVersion !== "1.0") hold("$.schemaVersion", "Expected version 1.0.");
  const tolerance = decimal(input.toleranceMm, true);
  if (tolerance === null) hold("$.toleranceMm", "Supply a non-negative decimal string in millimetres, at most 1000000 with up to six decimal places.");
  const values = {};
  for (const side of ["source", "candidate"]) {
    const record = input[side];
    const path = `$.${side}`;
    if (!isRecord(record)) { hold(path, "Expected a measurement record."); continue; }
    only(record, ["itemId", "basis", "evidenceRef", ...axes], path);
    for (const field of ["itemId", "evidenceRef"]) {
      if (typeof record[field] !== "string" || !record[field].trim() || record[field] !== record[field].trim())
        hold(`${path}.${field}`, "Supply a non-empty string without leading or trailing whitespace.");
    }
    if (!["product", "package"].includes(record.basis)) hold(`${path}.basis`, "State product or package explicitly.");
    values[side] = {};
    for (const axis of axes) {
      const measure = record[axis];
      const at = `${path}.${axis}`;
      if (!isRecord(measure)) { hold(at, "Supply a value and unit for this named axis."); continue; }
      only(measure, ["value", "unit"], at);
      const value = decimal(measure.value);
      if (value === null) hold(`${at}.value`, "Supply a positive decimal string, at most 1000000 with up to six decimal places. Ranges and nominal sizes need review.");
      if (typeof measure.unit !== "string" || !Object.hasOwn(factors, measure.unit)) hold(`${at}.unit`, "Supported units are mm, cm, m, and in; no unit is inferred.");
      else if (value !== null) values[side][axis] = value * factors[measure.unit];
    }
  }
  if (isRecord(input.source) && isRecord(input.candidate)) {
    if (input.source.itemId !== input.candidate.itemId) hold("$.candidate.itemId", "Records identify different items; resolve identity before comparison.");
    if (input.source.basis !== input.candidate.basis) hold("$.candidate.basis", "Product and package measurements cannot be compared as the same fact.");
  }
  if (findings.length) return result("hold");
  const normalized = Object.fromEntries(["source", "candidate"].map(side => [side,
    Object.fromEntries(axes.map(axis => [axis, { value: millimetres(values[side][axis]), unit: "mm" }]))]));
  for (const axis of axes) {
    const signed = values.candidate[axis] - values.source[axis];
    const difference = signed < 0n ? -signed : signed;
    if (difference > tolerance * 10n) findings.push({
      code: "dimension-mismatch", path: `$.candidate.${axis}`, message: "Difference exceeds the supplied tolerance.",
      sourceMm: millimetres(values.source[axis]), candidateMm: millimetres(values.candidate[axis]),
      differenceMm: millimetres(difference), toleranceMm: millimetres(tolerance * 10n),
    });
  }
  return result(findings.length ? "mismatch" : "match", normalized);
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) {
  if (process.argv.length !== 3) {
    process.stderr.write("Usage: node compare-product-dimensions.mjs input.json\n");
    process.exitCode = 2;
  } else {
    try {
      const output = compareDimensions(JSON.parse(readFileSync(process.argv[2], "utf8")));
      process.stdout.write(JSON.stringify(output, null, 2) + "\n");
      process.exitCode = output.status === "match" ? 0 : output.status === "mismatch" ? 1 : 2;
    } catch {
      process.stderr.write("Could not read or parse JSON input. No comparison was completed.\n");
      process.exitCode = 2;
    }
  }
}
